<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { open, save } from '@tauri-apps/plugin-dialog'
import { invoke } from '@tauri-apps/api/core'
import JsonTree from '@/components/JsonTree.vue'
import SitePreview from '@/components/SitePreview.vue'
import { autoNumberArticles, detectRole, humanSize, jsonError, langName, markdownStats, minifyJson, prettyJson, richIssues, transformRich } from '@/lib/editor-utils.js'

const tabs = ref([]); const activeId = ref(''); const explorer = ref([]); const root = ref(''); const showTree = ref(true); const showPreview = ref(true)
const interfaceLang = ref(localStorage.getItem('editor-lang') || 'ja'); const toast = ref(''); const findText = ref(''); const showFind = ref(false); const showEntry = ref(false)
const entry = ref({ version: '', date: new Date().toISOString().slice(0, 10), content: '' })
const active = computed(() => tabs.value.find((tab) => tab.id === activeId.value) || null)
const role = computed(() => active.value?.role || 'generic'); const lang = computed(() => active.value?.lang || interfaceLang.value)
const jsonValue = computed(() => { if (!active.value?.isJson) return null; try { return JSON.parse(active.value.text) } catch { return null } })
const parseError = computed(() => active.value?.isJson ? jsonError(active.value.text) : '')
const previewPayload = computed(() => !active.value ? { mode: 'generic', data: null } : active.value.isJson ? { mode: parseError.value ? 'generic' : role.value === 'i18n' ? 'i18n' : role.value === 'changelog' ? 'changelog' : 'generic', lang: lang.value, data: jsonValue.value, error: parseError.value } : { mode: 'markdown', lang: lang.value, data: active.value.text })
const status = computed(() => active.value ? `${role.value} · ${langName[lang.value] || '—'} · ${humanSize(active.value.text)}${active.value.dirty ? ' · Unsaved' : ''}` : 'Ready, meow~')
const stats = computed(() => active.value && !active.value.isJson ? markdownStats(active.value.text) : null)

function say(message) { toast.value = message; window.setTimeout(() => { if (toast.value === message) toast.value = '' }, 3400) }
function newTab(kind = 'json') { const id = crypto.randomUUID(); tabs.value.push({ id, path: '', name: kind === 'json' ? 'Untitled.json' : 'Untitled.md', isJson: kind === 'json', text: kind === 'json' ? '{\n  \n}' : '', dirty: false, role: 'generic', lang: null }); activeId.value = id }
async function chooseRoot() { const path = await open({ directory: true, multiple: false }); if (!path) return; root.value = path; explorer.value = await invoke('list_files', { root: path }); localStorage.setItem('editor-root', path) }
async function openFile(path) { const found = tabs.value.find((tab) => tab.path === path); if (found) { activeId.value = found.id; return }; const text = await invoke('read_text_file', { path }); const isJson = path.toLowerCase().endsWith('.json'); const detected = detectRole(path); const id = crypto.randomUUID(); tabs.value.push({ id, path, name: path.split(/[\\/]/).pop(), isJson, text, dirty: false, ...detected }); activeId.value = id }
async function chooseFile() { const path = await open({ multiple: false, filters: [{ name: 'Self-Info data', extensions: ['json', 'md', 'markdown'] }] }); if (path) openFile(path) }
async function persist(tab = active.value, forceSaveAs = false) { if (!tab) return; let target = tab.path; if (!target || forceSaveAs) target = await save({ defaultPath: tab.name, filters: [{ name: tab.isJson ? 'JSON' : 'Markdown', extensions: [tab.isJson ? 'json' : 'md'] }] }); if (!target) return; await invoke('write_text_file', { path: target, content: tab.text }); Object.assign(tab, { path: target, name: target.split(/[\\/]/).pop(), dirty: false, ...detectRole(target) }); say(`Saved ${tab.name}`) }
function closeTab(id) { const tab = tabs.value.find((item) => item.id === id); if (tab?.dirty && !confirm(`Discard unsaved changes in ${tab.name}?`)) return; tabs.value = tabs.value.filter((item) => item.id !== id); if (activeId.value === id) activeId.value = tabs.value.at(-1)?.id || '' }
function updateText(value) { if (active.value) { active.value.text = value; active.value.dirty = true } }
function formatJson(minify = false) { if (!active.value?.isJson) return; try { updateText(minify ? minifyJson(active.value.text) : prettyJson(active.value.text)); say(minify ? 'Minified JSON' : 'Formatted JSON') } catch { say(`JSON error: ${parseError.value}`) } }
function validate() { say(parseError.value ? `Invalid JSON: ${parseError.value}` : 'JSON is valid ★') }
function syncFromTree(next) { updateText(JSON.stringify(next, null, 2)) }
function richTool(mode) { if (!jsonValue.value) return; if (mode === 'check') { const issues = richIssues(jsonValue.value); say(issues.length ? `${issues.length} rich-text issue(s): ${issues[0]}` : 'Rich-text schema is happy ★'); return } const result = transformRich(jsonValue.value, mode); updateText(JSON.stringify(result.value, null, 2)); say(`${mode}: ${result.count} field(s) changed`) }
function addEntry() { if (!Array.isArray(jsonValue.value)) { say('Changelog must be a JSON array'); return }; showEntry.value = true }
function confirmEntry() { const list = [...jsonValue.value, { ...entry.value }]; updateText(JSON.stringify(list, null, 2)); showEntry.value = false; entry.value = { version: '', date: new Date().toISOString().slice(0, 10), content: '' }; say('Changelog entry added') }
function numberLegal() { if (active.value) updateText(autoNumberArticles(active.value.text, lang.value)) }
function exportHtml() { if (!active.value) return; const blob = new Blob([active.value.isJson ? `<pre>${escapeHtml(active.value.text)}</pre>` : active.value.text], { type: 'text/html' }); const url = URL.createObjectURL(blob); const link = Object.assign(document.createElement('a'), { href: url, download: `${active.value.name}.html` }); link.click(); URL.revokeObjectURL(url) }
function escapeHtml(value) { return value.replace(/[&<>]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[char]) }
function runFind() { const element = document.querySelector('.code-area'); if (element && findText.value) { const index = active.value.text.toLowerCase().indexOf(findText.value.toLowerCase()); if (index >= 0) { element.focus(); element.setSelectionRange(index, index + findText.value.length); say('Found it, meow~') } else say('No matches') } }
async function consistency() { if (!root.value) { say('Choose the project folder first'); return }; const result = await invoke('check_i18n_consistency', { root: root.value }); say(result.ok ? `All ${result.keys} top-level keys match ★` : result.message) }
function keydown(event) { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 's') { event.preventDefault(); persist() } if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'o') { event.preventDefault(); chooseFile() } if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'f') { event.preventDefault(); showFind.value = !showFind.value } if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'n') { event.preventDefault(); newTab('json') } }
watch(interfaceLang, (value) => { localStorage.setItem('editor-lang', value); document.documentElement.dataset.lang = value })
onMounted(async () => { document.documentElement.dataset.lang = interfaceLang.value; const saved = localStorage.getItem('editor-root'); if (saved) { try { root.value = saved; explorer.value = await invoke('list_files', { root: saved }) } catch {} } window.addEventListener('keydown', keydown); newTab('json') })
</script>

<template>
  <div class="editor-shell">
    <header class="topbar glass"><div class="brand"><span class="brand-orb">✦</span><div><strong>Self-Info Editor</strong><small>Liquid Glass Content Studio</small></div></div><div class="toolbar"><button class="tool-btn" @click="newTab('json')">＋ JSON</button><button class="tool-btn" @click="newTab('markdown')">＋ MD</button><button class="tool-btn" @click="chooseFile">Open</button><button class="primary-btn" @click="persist">Save</button><button class="tool-btn" @click="persist(active, true)">Save As</button><select v-model="interfaceLang"><option value="ja">日本語</option><option value="en">English</option><option value="zh-Hans">简体中文</option><option value="zh-TW">繁體中文</option></select></div></header>
    <section class="tabbar glass"><button v-for="tab in tabs" :key="tab.id" class="tab" :class="{ active: tab.id === activeId }" @click="activeId = tab.id">{{ tab.name }}{{ tab.dirty ? ' *' : '' }}<span @click.stop="closeTab(tab.id)">×</span></button></section>
    <main class="workspace"><aside class="sidebar glass glass-card"><div class="panel-title"><b>Project Files</b><button class="icon-btn" @click="chooseRoot">⌘</button></div><p class="root-path">{{ root || 'Choose a project folder' }}</p><div class="file-list"><button v-for="file in explorer" :key="file" class="file-row" :class="{ selected: active?.path === file }" @click="openFile(file)"><span>{{ file.endsWith('.json') ? '{ }' : 'M↓' }}</span>{{ file.replace(root + '/', '') }}</button></div><div class="side-actions"><button class="tool-btn" @click="consistency">Check i18n</button></div></aside>
      <section class="editor-panel glass glass-card"><template v-if="active"><div class="contextbar"><span class="chip">{{ role }}</span><span class="muted">{{ langName[lang] || 'Generic' }}</span><span class="spacer" /><button v-if="active.isJson" class="tool-btn" @click="formatJson()">Format</button><button v-if="active.isJson" class="tool-btn" @click="formatJson(true)">Minify</button><button v-if="active.isJson" class="tool-btn" @click="validate">Validate</button><template v-if="role === 'i18n'"><button class="tool-btn" @click="richTool('check')">Schema</button><button class="tool-btn" @click="richTool('wrap')">Wrap</button><button class="tool-btn" @click="richTool('unwrap')">Unwrap</button><button class="tool-btn" @click="richTool('normalize')">Normalize</button></template><button v-if="role === 'changelog'" class="tool-btn" @click="addEntry">Add entry</button><button v-if="role === 'legal'" class="tool-btn" @click="numberLegal">Auto-number</button><button v-if="!active.isJson" class="tool-btn" @click="exportHtml">Export HTML</button><button class="tool-btn" @click="showTree = !showTree">{{ showTree ? 'Hide tree' : 'Tree' }}</button><button class="tool-btn" @click="showPreview = !showPreview">{{ showPreview ? 'Hide preview' : 'Preview' }}</button></div><div v-if="showFind" class="findbar"><input v-model="findText" placeholder="Find…" @keyup.enter="runFind" /><button class="tool-btn" @click="runFind">Find</button></div><div class="editor-content" :class="{ 'tree-open': showTree, 'preview-open': showPreview }"><div v-if="showTree" class="tree-pane"><JsonTree v-if="active.isJson && jsonValue !== null" :value="jsonValue" @replace="syncFromTree" /><p v-else class="muted">{{ active.isJson ? (parseError || 'No data') : 'Tree view is available for JSON files.' }}</p></div><textarea class="code-area" spellcheck="false" :value="active.text" @input="updateText($event.target.value)" /><div v-if="showPreview" class="preview-pane"><SitePreview :payload="previewPayload" /></div></div></template><div v-else class="empty">Open or create a JSON / Markdown file to begin.</div></section></main>
    <footer class="statusbar glass"><span>{{ status }}</span><span v-if="stats">{{ stats.lines }} lines · {{ stats.words }} words · {{ stats.cjk }} CJK · ~{{ stats.pages }} pages</span><span v-else>{{ parseError ? parseError : 'Ln / Col ready' }}</span></footer>
    <div v-if="showEntry" class="dialog-backdrop"><form class="dialog glass" @submit.prevent="confirmEntry"><h3>Add Changelog Entry</h3><label>Version<input v-model="entry.version" required placeholder="1.4.0" /></label><label>Date<input v-model="entry.date" type="date" required /></label><label>Markdown<textarea v-model="entry.content" placeholder="What changed?" /></label><div class="dialog-actions"><button class="tool-btn" type="button" @click="showEntry = false">Cancel</button><button class="primary-btn" type="submit">Add entry</button></div></form></div><div v-if="toast" class="toast">{{ toast }}</div>
  </div>
</template>

<style scoped>
.editor-shell { display:grid; grid-template-rows:64px 42px minmax(0,1fr) 32px; height:100%; gap:8px; padding:10px; }
.topbar,.tabbar,.statusbar { border-radius:18px; display:flex; align-items:center; padding:8px 12px; }
.topbar{justify-content:space-between;gap:10px}.brand{display:flex;align-items:center;gap:10px}.brand-orb{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:linear-gradient(135deg,#c9a6ff,#ffa6d3);box-shadow:0 0 25px rgba(201,166,255,.7)}.brand small{display:block;color:rgba(255,255,255,.6);font-size:11px}.toolbar{display:flex;gap:6px;align-items:center;flex-wrap:wrap}.tabbar{gap:5px;overflow:auto}.tab{white-space:nowrap;color:rgba(255,255,255,.74);background:transparent;border:0;border-radius:10px;padding:7px 10px;cursor:pointer}.tab.active{background:rgba(255,255,255,.13);color:#fff}.tab span{margin-left:9px;color:#ffa6d3}.workspace{min-height:0;display:grid;grid-template-columns:250px minmax(0,1fr);gap:8px}.sidebar,.editor-panel{min-height:0}.sidebar{padding:14px;display:flex;flex-direction:column}.panel-title,.contextbar,.statusbar{display:flex;align-items:center;gap:8px}.root-path{margin:7px 0 11px;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:rgba(255,255,255,.55)}.file-list{overflow:auto;display:grid;gap:2px}.file-row{display:flex;gap:7px;text-align:left;border:0;background:transparent;color:rgba(255,255,255,.75);padding:7px;border-radius:8px;cursor:pointer;font-size:11px;word-break:break-all}.file-row:hover,.file-row.selected{background:rgba(255,255,255,.1);color:#fff}.side-actions{margin-top:auto;padding-top:12px}.editor-panel{display:flex;flex-direction:column;overflow:hidden}.contextbar{padding:9px 12px;border-bottom:1px solid rgba(255,255,255,.1);overflow:auto;flex-wrap:wrap}.spacer{flex:1}.findbar{padding:6px 12px;display:flex;gap:7px;background:rgba(0,0,0,.13)}.findbar input{color:#fff;background:rgba(0,0,0,.25);border:1px solid rgba(255,255,255,.15);border-radius:8px;padding:6px;flex:1}.editor-content{display:grid;min-height:0;flex:1;grid-template-columns:minmax(0,1fr)}.editor-content.tree-open{grid-template-columns:260px minmax(260px,1fr)}.editor-content.preview-open{grid-template-columns:minmax(0,1fr) minmax(300px,.9fr)}.editor-content.tree-open.preview-open{grid-template-columns:230px minmax(260px,1fr) minmax(300px,.9fr)}.tree-pane,.preview-pane{overflow:auto;background:rgba(5,3,14,.2);border-right:1px solid rgba(255,255,255,.09)}.tree-pane{padding:10px}.preview-pane{border-left:1px solid rgba(255,255,255,.09);border-right:0}.empty{display:grid;place-items:center;min-height:300px;color:rgba(255,255,255,.6)}.statusbar{justify-content:space-between;color:rgba(255,255,255,.72);font-size:11px}@media(max-width:1050px){.workspace{grid-template-columns:200px minmax(0,1fr)}.editor-content.preview-open{grid-template-columns:minmax(0,1fr) minmax(260px,.8fr)}.editor-content.tree-open.preview-open{grid-template-columns:minmax(0,1fr) minmax(260px,.8fr)}.tree-pane{display:none}}@media(max-width:760px){.workspace{grid-template-columns:1fr}.sidebar{display:none}.topbar{height:auto}.toolbar{justify-content:flex-end}.editor-shell{grid-template-rows:auto 42px minmax(0,1fr) 32px}.editor-content.preview-open{grid-template-columns:1fr}.preview-pane{display:none}}
</style>
